// Characterization tests: pin the HTTP behaviour clients see today,
// including quirks (e.g. 200 for unknown order). Don't "fix" these silently.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 2.5, C: 33.33 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})

test('POST /orders creates an order and returns 201 with id, items, total', async () => {
  const items = [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }]
  const res = await post({ items })
  assert.equal(res.status, 201)
  assert.match(res.headers.get('content-type'), /^application\/json/)
  const order = await res.json()
  assert.deepEqual(Object.keys(order).sort(), ['id', 'items', 'total'])
  assert.equal(typeof order.id, 'string')
  assert.deepEqual(order.items, items)
  assert.equal(order.total, 25)
})

test('ids are distinct, numeric strings', async () => {
  const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.match(a.id, /^\d+$/)
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total is floored to a whole number', async () => {
  const order = await (await post({ items: [{ sku: 'C', qty: 1 }] })).json()
  assert.equal(order.total, 33)
})

test('no discount at exactly 100', async () => {
  const order = await (await post({ items: [{ sku: 'A', qty: 10 }] })).json()
  assert.equal(order.total, 100)
})

test('10% discount applies when raw total is over 100', async () => {
  const order = await (await post({ items: [{ sku: 'A', qty: 11 }] })).json()
  assert.equal(order.total, 99) // 110 - 11
  const big = await (await post({ items: [{ sku: 'A', qty: 20 }] })).json()
  assert.equal(big.total, 180)
})

test('discount is applied before flooring', async () => {
  // 3 * 33.33 = 99.99 (no discount) -> 99 ; 4 * 33.33 = 133.32 -> 119.988 -> 119
  assert.equal((await (await post({ items: [{ sku: 'C', qty: 3 }] })).json()).total, 99)
  assert.equal((await (await post({ items: [{ sku: 'C', qty: 4 }] })).json()).total, 119)
})

test('multiple line items are summed', async () => {
  const order = await (await post({ items: [{ sku: 'A', qty: 1 }, { sku: 'B', qty: 4 }, { sku: 'C', qty: 1 }] })).json()
  assert.equal(order.total, 53) // 10 + 10 + 33.33
})

for (const [name, body, raw] of [
  ['missing items', {}],
  ['empty items', { items: [] }],
  ['items not an array', { items: 'A' }],
  ['invalid JSON', null, '{nope'],
]) {
  test(`POST /orders with ${name} -> 400 items required`, async () => {
    const res = await post(body, raw)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  })
}

test('empty body -> 400', async () => {
  const res = await post(null, '')
  assert.equal(res.status, 400)
  assert.deepEqual(await res.json(), { error: 'items required' })
})

test('rejected orders are not stored / do not consume ids', async () => {
  const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  await post({ items: [] })
  const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('GET /orders/:id returns the stored order with 200', async () => {
  const created = await (await post({ items: [{ sku: 'B', qty: 4 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.match(res.headers.get('content-type'), /^application\/json/)
  assert.deepEqual(await res.json(), created)
})

test('GET unknown order returns 200 (not 404) with { error: "not found" }', async () => {
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and methods -> 404 no route', async () => {
  for (const [method, path] of [
    ['GET', '/'], ['GET', '/orders'], ['GET', '/orders/1/extra'],
    ['PUT', '/orders'], ['DELETE', '/orders/1'], ['POST', '/orders/1'],
  ]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})

test('query string is ignored for routing', async () => {
  const created = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}?x=1`)
  assert.deepEqual(await res.json(), created)
})
